/* Stand-in for schilytools' <schily/mconfig.h>.
 *
 * The point of this directory is that the vendored libedc sources stay
 * byte-identical to upstream (see ../README.md), which means honouring the
 * include names they use. Upstream this header is generated by schilytools'
 * own autoconf and carries hundreds of HAVE_* results; edc_ecc.c tests exactly
 * one of them. */

#ifndef MKDCDISC_SCHILY_MCONFIG_H
#define MKDCDISC_SCHILY_MCONFIG_H

/* The prototype guard every declaration in ecc.h and edc.h is wrapped in.
 * Upstream expands it to nothing on a compiler too old for prototypes; every
 * compiler mkdcdisc builds with has them, so it just hands the argument list
 * back. */
#ifndef __PR
#define __PR(a) a
#endif

/* Upstream spells `const` this way so it can drop the qualifier on a compiler
 * that lacks it. It has to live here rather than in utypes.h with the other
 * type names: edc_ecc.c uses it on line 4, for its sccsid[] version string,
 * which is before it includes anything but this header. */
#define UConst const

/* True on every platform mkdcdisc builds for. Saying so drops the fallback in
 * edc_ecc.c that would otherwise route memmove() through bcopy() and pull in
 * <schily/libport.h> -- which is why there is no libport.h shim here, and why
 * the edc_bcopy() this library used to carry is gone. */
#define HAVE_MEMMOVE 1

#endif /* MKDCDISC_SCHILY_MCONFIG_H */
